const PAGE="<!doctype html>\n<html lang=\"ar\" dir=\"rtl\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\"><meta name=\"theme-color\" content=\"#674D34\"><title>مستندات الذات | ATHAT Docs</title><link rel=\"icon\" type=\"image/png\" href=\"data:image/png;base64,\"><link rel=\"apple-touch-icon\" href=\"data:image/png;base64,\"><meta name=\"description\" content=\"مستندات الذات: قوالب A4 وتوثيق الشواهد وأرشيف الأعمال وملف الإنجاز المحلي.\"><style>\n:root{font-family:system-ui,\"Tahoma\",Arial,sans-serif;color:#5A422B;background:#E9DEC9}*{box-sizing:border-box}body{margin:0}button,input,select,textarea{font:inherit}button{cursor:pointer}button:disabled{opacity:.5;cursor:not-allowed}header.top{background:#5A422B;color:#fff;padding:17px max(16px,calc((100vw - 1120px)/2));display:flex;align-items:center;justify-content:space-between;gap:12px}header.top b{font-size:19px}header.top small{display:block;color:#F1D9B1}header.top .brand{display:flex;gap:10px;align-items:center}.logo{display:grid;place-items:center;background:#BC9C6B;border-radius:13px;width:44px;height:44px;color:#5A422B;font-size:24px}main{max-width:1120px;margin:auto;padding:20px 15px 80px}.hero{background:#674D34;border-radius:20px;color:white;padding:24px;display:grid;gap:10px}.hero h1{margin:0;font-size:clamp(22px,4vw,32px)}.hero p{margin:0;color:#EEE1C9}.actions{display:flex;flex-wrap:wrap;gap:9px;margin:12px 0}.btn,.actions button,.actions label{padding:11px 16px;border:1px solid #d7d9d1;border-radius:10px;background:#fff;color:#5A422B;display:inline-flex;align-items:center;gap:7px;font-weight:650}.primary,.actions .primary{background:#BC9C6B;color:#28392f;border-color:#BC9C6B}.actions input[type=file]{display:none}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:16px 0}.metrics article,.panel{background:white;border:1px solid #E3D8C6;border-radius:16px;padding:18px}.metrics strong{display:block;font-size:25px}.metrics span{font-size:13px;color:#806E58}.panel{margin-bottom:15px}.panel h2{font-size:19px;margin:0 0 13px}.templates{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.template{padding:16px;border:1px solid #E3D8C6;border-radius:12px;background:#FAF4E8;text-align:right;color:#5A422B;display:grid;gap:8px}.template span{font-size:24px;color:#aa8751}.template small,.muted{color:#806E58;font-size:12px}.row{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap}.tabs{display:flex;gap:8px;margin-bottom:13px;flex-wrap:wrap}.tabs button{border:1px solid #e4e4dc;border-radius:9px;padding:9px 14px;background:#f7f7f3;color:#5A422B}.tabs button.active{background:#5A422B;color:#fff}.search{padding:11px;border:1px solid #DACDB9;border-radius:10px;min-width:180px;max-width:100%}.docs{display:grid;gap:8px}.doc{border:1px solid #E3D8C6;border-radius:12px;padding:12px;display:flex;align-items:center;gap:10px;flex-wrap:wrap}.doc .info{flex:1;min-width:140px}.doc b,.doc small{display:block}.doc small{color:#806E58;margin-top:4px}.doc button{background:#fff;color:#674D34;border:1px solid #E3D8C6;padding:8px;border-radius:9px}.doc input[type=checkbox]{width:19px;height:19px}.editor{display:none}.editor.visible{display:block}.fields{display:grid;grid-template-columns:2fr 1fr 1fr;gap:9px}.fields input,.fields select,.editor textarea{width:100%;padding:12px;border:1px solid #d8dfd9;border-radius:9px;color:#5A422B;background:#fff}.paper{width:min(100%,210mm);min-height:160mm;background:white;margin:17px auto;padding:19mm 15mm;box-shadow:0 2px 15px #0000000a;border:1px solid #e7e5e0}.paper h3{text-align:center;margin:0 0 20px}.paper textarea{border:0;min-height:250px;line-height:2;resize:vertical}.evidence{display:grid;grid-template-columns:repeat(auto-fill,minmax(120px,1fr));gap:8px;margin:12px 0}.evidence .photo{border:1px solid #e2e3db;padding:7px;border-radius:9px}.evidence img{width:100%;height:105px;object-fit:contain}.evidence button{width:100%;padding:6px;border:1px solid #c8beb0;background:white;border-radius:8px}.notice{padding:12px;border-radius:11px;background:#fff8e9;border:1px solid #eddfc0;line-height:1.8;font-size:13px}.danger{color:#a13b31!important}.hidden{display:none!important}#toast{position:fixed;bottom:18px;left:15px;right:15px;max-width:560px;margin:auto;background:#5A422B;color:white;padding:13px 16px;border-radius:12px;box-shadow:0 5px 25px #0002;display:none;z-index:20}footer{font-size:12px;color:#806E58;text-align:center;margin:18px 0}#importPreview{max-height:260px;overflow:auto}.preview-row{display:flex;gap:10px;align-items:center;padding:8px;border-bottom:1px solid #eee}.preview-row span{flex:1;font-size:13px;overflow-wrap:anywhere}@media(max-width:650px){main{padding:12px 10px 60px}.templates{grid-template-columns:repeat(2,1fr)}.fields{grid-template-columns:1fr}.metrics article{padding:12px}.metrics strong{font-size:20px}.panel{padding:13px}.paper{padding:9mm 7mm;min-height:120mm}.doc{gap:6px}.doc button{padding:7px}.hero{padding:17px}}\n\n/* Official unified A4 workspace based on ATHAT's original DocumentTemplate */\n.unified-groups{display:flex;gap:8px;overflow-x:auto;padding:3px 0 13px;scrollbar-width:thin}\n.unified-groups button{border:1px solid #DACDB9;background:#fff;color:#674D34;border-radius:999px;padding:9px 13px;white-space:nowrap}\n.unified-groups .active{background:#5A422B;color:#fff}\n.official-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:14px}\n.official-fields label{display:grid;gap:5px;font-size:13px;font-weight:650}\n.official-fields input,.official-fields textarea{width:100%;padding:11px;background:#fff;border:1px solid #d7ded8;border-radius:9px;line-height:1.8;color:#5A422B}\n.official-fields textarea{min-height:95px;resize:vertical}\n.official-fields .wide{grid-column:1/-1}\n.official-head{display:grid;grid-template-columns:1fr 75px 1fr;align-items:center;gap:8px;border-bottom:2px solid #939d99;padding-bottom:14px}\n.official-head .ministry{height:60px;display:grid;place-items:center;font-size:12px;text-align:center;border:1px solid #d8d8d8;border-radius:50%;color:#5e6b65}\n.official-head .org{display:grid;font-size:12px;gap:2px}\n.official-head .ref{display:grid;font-size:11px;gap:3px;text-align:left}\n.official-head .ref input{width:100%;min-width:0;font-size:12px;border:1px solid #dedede;border-radius:6px;padding:5px}\n.official-title{text-align:center;font-size:21px;margin:19px 0}\n.official-foot{border-top:1px solid #c4c9c6;padding-top:12px;margin-top:22px;display:flex;justify-content:space-between;color:#627069;font-size:11px;gap:10px}\n.official-evidence-header{font-size:14px;border-bottom:1px solid #e4e4df;padding:8px 0;margin:10px 0}\n.unified-note{background:#F3E8D5;color:#745A3C;border:1px solid #DCCBB0;border-radius:12px;padding:11px;font-size:12px;line-height:1.8}\n.mini-link{background:none;border:0;color:#9e443e;text-decoration:underline}\n@media(max-width:660px){.official-fields{grid-template-columns:1fr}.official-head{grid-template-columns:1fr 52px 1fr}.official-head .ministry{height:48px}.official-head .org,.official-head .ref{font-size:10px}}\n\n/* Authentic parchment-and-walnut identity derived from user's reference document. */\n:root{--athat-brown:#63492F;--athat-walnut:#503821;--athat-parchment:#E9DEC9;--athat-paper:#FBF5E9;--athat-sand:#F3E8D4;--athat-gold:#B99966;--athat-text:#453321;--athat-line:#D9CBB6;color:var(--athat-text);background:var(--athat-parchment)}\nbody{background:var(--athat-parchment);color:var(--athat-text)}\nheader.top{background:#63492F;color:#FFF7EB;border-bottom:2px solid #B99966}\nheader.top small{color:#F2E4CE}\n.logo{background:#F1E1C4;color:#644930}\n.hero{background:#F8F0E1;border:1px solid #DCC9AC;color:var(--athat-text);box-shadow:0 2px 13px #694a2912}\n.hero h1{color:#493520}\n.hero p{color:#806A51}\n.metrics article,.panel{background:#FBF5E9;border:1px solid #E0D2BC;box-shadow:0 1px 10px #7054370d}\n.metrics strong{color:#63492F}\n.metrics span,.muted,.template small,.doc small{color:#83735D}\n.template{background:#F5EAD7;border-color:#DECEB5;color:#553E29}\n.template:hover,.template:focus-visible{border-color:#9E784A;background:#F0DFC1}\n.template span{color:#9E784A}\n.primary,.actions .primary{background:#63492F;color:#FFF7E8;border-color:#63492F}\n.actions .primary:hover{background:#4F3924}\n.btn,.actions button,.actions label{border-color:#DACBB5;color:#523D28;background:#FFF9EE}\n.tabs button{background:#F7EEDD;color:#5A4330;border-color:#DCCBB0}\n.tabs button.active,.unified-groups button.active{background:#63492F;color:#FFF7EB;border-color:#63492F}\n.unified-groups button{background:#FFF9EF;border-color:#DDCFB8;color:#63492F}\n.search,.fields input,.fields select,.editor textarea,.official-fields input,.official-fields textarea{background:#FFFDF7;border-color:#D8C9B3;color:#493622}\n.paper{background:#FFFAEF;border-color:#DECDB2;box-shadow:0 8px 24px #65492c16}\n.official-head{border-color:#6D4C2D}\n.official-head .ministry{border-color:#BDA77F;color:#63492F}\n.official-title,.paper h3{color:#493520}\n.official-fields label{color:#63492F}\n.official-evidence-header,.official-foot{border-color:#CBB89A;color:#755B3F}\n.doc{border-color:#E0D2BC;background:#FFF9EF}\n.doc button{background:#F7EDDC;color:#5B432E;border-color:#D9C8AD}\n.unified-note,.notice{background:#F5E9D2;color:#684D31;border-color:#E2CEAD}\n#toast{background:#63492F;color:#FFF7EB}\n:focus-visible{outline:3px solid #B99966;outline-offset:2px}\n\n.ai-panel{border:1px solid #d6bd98;background:#fff8eb;border-radius:14px;padding:14px;margin:16px 0;display:grid;gap:12px}\n.ai-panel h3{margin:0;color:#63492f;font-size:18px}\n.ai-panel p{font-size:12px;line-height:1.9;color:#745b3c;margin:0}\n.ai-login,.ai-controls{display:flex;gap:9px;flex-wrap:wrap;align-items:center}\n.ai-login input,.ai-panel select,.ai-panel textarea{font:inherit;padding:10px;border:1px solid #d6c6ab;border-radius:9px;max-width:100%;background:#fffcf6;color:#503a26}\n.ai-login input{flex:1 1 180px;min-width:0}\n.ai-panel textarea{width:100%;min-height:90px;resize:vertical;line-height:1.85}\n.ai-panel button{border:1px solid #c5ab85;background:#63492f;color:#fff9ee;border-radius:9px;padding:10px 14px;font-weight:700}\n.ai-panel button.secondary{background:#fffaf1;color:#644b30}\n.ai-panel button:disabled{opacity:.5}\n.ai-result{white-space:pre-wrap;line-height:1.9;border:1px solid #e7d7be;background:#fffcf5;padding:12px;border-radius:10px;max-height:360px;overflow:auto;font-size:13px}\n.ai-suggestions{display:grid;gap:8px}\n.ai-suggestion{border:1px solid #dfcbb0;padding:10px;border-radius:9px;background:#fffdf8}\n.ai-suggestion b{color:#6a4b2d;font-size:13px}\n.ai-suggestion p{white-space:pre-wrap;line-height:1.7;margin:6px 0;font-size:13px}\n.ai-confirm{font-size:12px;display:flex;gap:8px;align-items:start}\n.ai-confirm input{margin-top:4px}\n.ai-error{color:#9b3535!important}\n\n#authGate{min-height:calc(100dvh - 86px);display:grid;place-items:center;padding:24px 14px}\n#authGate[hidden],#appMain[hidden],#sessionPanel[hidden]{display:none!important}\n.auth-card{max-width:460px;width:100%;display:grid;gap:13px;background:#FBF5E9;border:1px solid #D8C5A7;border-radius:22px;padding:24px;box-shadow:0 8px 35px #53391c16}\n.auth-card h1{margin:0;font-size:25px;color:#63492F}.auth-card p{font-size:13px;line-height:1.8;color:#806B52;margin:0}\n.auth-card label{display:grid;gap:6px;font-size:13px;font-weight:700}\n.auth-card input{width:100%;padding:12px;border:1px solid #D8C7AC;border-radius:10px;background:#FFFCF4;color:#503A26;font:inherit;direction:ltr}\n.auth-tabs{display:grid;grid-template-columns:1fr 1fr;gap:8px}\n.auth-tabs button{background:#F4E6D0;border:1px solid #D8C7AC;border-radius:10px;padding:11px;color:#63492F}\n.auth-tabs button.selected,.auth-submit{background:#63492F!important;color:#FFF9EB!important;border:0;border-radius:10px;padding:12px;font-weight:700}\n#authMsg{font-size:12px;min-height:20px;color:#9E352E;line-height:1.8}\n#sessionPanel{display:flex;align-items:center;gap:9px;flex-wrap:wrap}\n#sessionPanel button{border:1px solid #CBB28D;color:#FFF7E5;background:transparent;border-radius:8px;padding:8px}\n.logo{background:transparent!important;width:49px;height:49px;border-radius:11px;overflow:hidden;flex-shrink:0}.logo img{display:block;width:100%;height:100%;object-fit:contain;border-radius:10px}</style></head><body>\n<header class=\"top\"><div class=\"brand\"><div class=\"logo\"><img src=\"data:image/png;base64,\" alt=\"شعار مستندات الذات\" width=\"44\" height=\"44\"></div><div><b>مستندات الذات</b><small>ATHAT Docs · أعمالك وشواهدك</small></div></div><div id=\"sessionPanel\" hidden><small id=\"accountName\"></small><button id=\"logoutDocs\" type=\"button\">تسجيل خروج</button></div></header>\n<section id=\"authGate\" aria-label=\"تسجيل الدخول\">\n<div class=\"auth-card\"><h1>مستندات الذات</h1><p>سجّل الدخول بالبريد الإلكتروني وكلمة المرور. حسابك يفتح أرشيفك الخاص على هذا الجهاز.</p>\n<div class=\"auth-tabs\"><button id=\"tabLogin\" type=\"button\" class=\"selected\">تسجيل الدخول</button><button id=\"tabRegister\" type=\"button\">إنشاء حساب</button></div>\n<label id=\"registerNameWrap\" hidden>اسم صاحب الحساب<input id=\"registerName\" autocomplete=\"name\" dir=\"rtl\" placeholder=\"الاسم الكامل\"></label>\n<label>البريد الإلكتروني<input id=\"emailInput\" type=\"email\" autocomplete=\"email\" inputmode=\"email\" placeholder=\"name@example.com\" required></label>\n<label>كلمة المرور<input id=\"passwordInput\" type=\"password\" autocomplete=\"current-password\" placeholder=\"8 أحرف على الأقل\" required></label>\n<label id=\"mfaWrap\" hidden>رمز المصادقة الإضافية<input id=\"mfaInput\" inputmode=\"numeric\" autocomplete=\"one-time-code\" placeholder=\"رمز التحقق\"></label>\n<button id=\"submitAuth\" class=\"auth-submit\" type=\"button\">تسجيل الدخول</button><p id=\"authMsg\" role=\"status\" aria-live=\"polite\"></p>\n<p>لا يلزم رقم جوال أو واتساب. المستندات تُحفظ محليًا لكل حساب، ويمكنك حفظ نسخة احتياطية من داخل الموقع.</p></div></section><main id=\"appMain\" hidden><section class=\"hero\"><h1>مساحة أعمالك، ببساطة</h1><p>نماذج الذات الموحدة A4 · سجلات منظمة · شواهد داخل المستند · أرشيف وملف إنجاز.</p><div class=\"actions\"><button class=\"primary\" id=\"newBtn\">＋ مستند جديد</button><button id=\"backupBtn\">↓ نسخة احتياطية</button><label>↑ استعادة نسخة<input id=\"restoreFile\" type=\"file\" accept=\".json,application/json\"></label></div></section>\n<div class=\"metrics\"><article><strong id=\"countAll\">0</strong><span>الأعمال المحفوظة</span></article><article><strong id=\"countDone\">0</strong><span>المكتمل</span></article><article><strong id=\"countArchive\">0</strong><span>المؤرشف</span></article></div>\n<section class=\"panel\"><h2>النماذج الموحدة A4</h2><p class=\"muted\">اختر المجموعة ثم افتح نموذجًا؛ لكل سجل حقوله الخاصة.</p><nav class=\"unified-groups\" id=\"groups\" aria-label=\"مجموعات النماذج\"></nav><div class=\"templates\" id=\"templates\"></div></section>\n<section class=\"panel editor\" id=\"editor\">\n<div class=\"row\"><h2 id=\"editorHeading\">النموذج الموحد A4</h2><button class=\"btn\" id=\"closeEditor\">إغلاق المحرر</button></div>\n<div class=\"fields\"><input id=\"docTitle\" placeholder=\"عنوان السجل\" aria-label=\"عنوان السجل\"><input id=\"docKind\" placeholder=\"نوع السجل\" aria-label=\"نوع السجل\" readonly><select id=\"docStatus\" aria-label=\"حالة المستند\"><option>مسودة</option><option>مكتمل</option><option>مؤرشف</option></select></div>\n<section class=\"ai-panel\" id=\"athatAi\"><h3>✦ ذكاء الذات للمستندات</h3><p>صياغة المستندات والتعبئة الذكية وإعادة الصياغة عبر خدمة الذكاء الأصلية في الذات. لا يُرسل أي محتوى دون ضغط «توليد» بعد الموافقة. راجع المقترحات قبل تطبيقها.</p>\n<div class=\"ai-login hidden\" id=\"aiLogin\"><input id=\"aiUsername\" type=\"text\" autocomplete=\"username\" placeholder=\"بريد أو اسم مستخدم الذات\" aria-label=\"اسم المستخدم في الذات\"><input id=\"aiPassword\" type=\"password\" autocomplete=\"current-password\" placeholder=\"كلمة مرور الذات\" aria-label=\"كلمة المرور في الذات\"><button type=\"button\" id=\"aiSignIn\">اتصال بذكاء الذات</button></div>\n<div id=\"aiConnected\" class=\"hidden\"><div class=\"ai-controls\"><span id=\"aiAccountLabel\">متصل بخدمة الذات</span><button type=\"button\" class=\"secondary\" id=\"aiSignOut\">فصل الاتصال</button></div></div>\n<div class=\"ai-controls\"><select id=\"aiMode\" aria-label=\"طريقة مساعدة الذكاء\"><option value=\"fill\">تعبئة الحقول الفارغة</option><option value=\"rewrite\">تحسين صياغة الحقول النصية</option><option value=\"document\">إنشاء مسودة متكاملة</option><option value=\"summary\">تلخيص محتوى المستند</option></select></div>\n<textarea id=\"aiBrief\" placeholder=\"اكتب وصف العمل أو التعليمات للذكاء، دون أسماء طلاب أو معلومات حساسة…\" aria-label=\"تعليمات الذكاء\"></textarea>\n<label class=\"ai-confirm\"><input type=\"checkbox\" id=\"aiConsent\"><span>أوافق على إرسال الوصف والحقول النصية المسموح بها إلى خدمة ذكاء الذات لغرض هذا الطلب فقط. لا تُرسل الصور أو الأسماء أو التواريخ أو الأرقام تلقائيًا.</span></label>\n<div class=\"ai-controls\"><button type=\"button\" id=\"aiGenerate\">✦ توليد المقترحات</button><button type=\"button\" class=\"secondary hidden\" id=\"aiApplyAll\">تطبيق المقترحات المحددة</button></div>\n<p id=\"aiNotice\" role=\"status\" aria-live=\"polite\"></p><div id=\"aiSuggestions\" class=\"ai-suggestions\"></div></section>\n<div class=\"paper\">\n<div class=\"official-head\"><div class=\"org\"><strong>المملكة العربية السعودية</strong><span>وزارة التعليم</span><input id=\"schoolName\" placeholder=\"اسم المدرسة / الجهة\" aria-label=\"اسم المدرسة\"></div><div class=\"ministry\" aria-label=\"هوية وزارة التعليم\">وزارة<br>التعليم</div><div class=\"ref\"><label>رقم المستند<input id=\"documentNumber\" placeholder=\"اختياري\"></label><label>التاريخ الهجري<input id=\"hijriDate\" placeholder=\"١٤٤٨/٠٥/...\" aria-label=\"التاريخ الهجري\"></label></div></div>\n<h3 class=\"official-title\" id=\"paperTitle\">عنوان النموذج</h3><div id=\"officialFields\" class=\"official-fields\"></div><h4 class=\"official-evidence-header\">الشواهد المصورة داخل السجل</h4><div id=\"evidencePreview\" class=\"evidence\"></div><div class=\"official-foot\"><span>الذات | مستندات A4</span><span>سجل موحد · جاهز للطباعة</span></div></div>\n<label class=\"btn\">إضافة صور الشواهد<input id=\"photoInput\" type=\"file\" accept=\"image/png,image/jpeg,image/webp\" multiple style=\"display:block;margin-top:8px\"></label>\n<p class=\"muted\">حتى 10 صور لكل مستند، بحد 5 ميجابايت للصورة. تُحفظ محليًا.</p>\n<div class=\"actions\"><button class=\"primary\" id=\"saveDoc\">حفظ وأرشفة</button><button id=\"printDoc\">معاينة وطباعة A4</button></div></section>\n<section class=\"panel\"><div class=\"row\"><h2>أعمالي والأرشيف</h2><input class=\"search\" id=\"search\" type=\"search\" placeholder=\"ابحث في مستنداتك\" aria-label=\"البحث في المستندات\"></div><div class=\"tabs\"><button class=\"active\" data-tab=\"all\">أعمالي</button><button data-tab=\"archive\">الأرشيف</button><button data-tab=\"portfolio\">ملف الإنجاز</button></div><div class=\"docs\" id=\"docs\"></div><div class=\"actions hidden\" id=\"portfolioActions\"><button class=\"primary\" id=\"printPortfolio\">إنشاء ملف إنجاز PDF من المحدد</button></div></section>\n<p class=\"unified-note\">بدأت نسخة النماذج الموحدة بمساحة أعمال نظيفة، ولا تستورد بيانات الذات أو Excel تلقائيًا. السجلات والشواهد تُحفظ في هذا الجهاز فقط. خذ نسخة احتياطية قبل مسح بيانات المتصفح.</p><div class=\"row\"><span class=\"muted\">إدارة مساحة العمل المحلية</span><button class=\"btn danger\" id=\"clearDocs\">مسح جميع مستندات هذا الجهاز</button></div><footer>مستندات الذات © 2026 · ATHAT Docs</footer></main><div id=\"toast\" role=\"status\" aria-live=\"polite\"></div>\n\n<script>\n(()=>{'use strict';\nconst $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c])),str=v=>String(v??'').trim();\nconst catalog=[\n{group:'التخطيط الإداري',title:'خطة التوجيه الطلابي',fields:['الأهداف|multi','محاور الخطة|multi','آلية التنفيذ|multi','الجدول الزمني','مؤشرات الإنجاز|multi']},\n{group:'التخطيط الإداري',title:'سجل العمل اليومي',fields:['العمل المسجل|multi','الفئة المستهدفة','مؤشر الإنجاز|multi','الشواهد المطلوبة|multi','الملاحظات|multi']},\n{group:'التخطيط الإداري',title:'لجنة التوجيه الطلابي',fields:['اسم اللجنة','أعضاء اللجنة|multi','اختصاصاتها|multi','القرارات والتوصيات|multi']},\n{group:'التخطيط الإداري',title:'التقارير الإرشادية',fields:['الأعمال المنفذة|multi','النتائج المثبتة|multi','التوصيات|multi']},\n{group:'التخطيط الإداري',title:'الإحالات',fields:['سبب الإحالة|multi','الجهة المحال إليها','الإجراءات المتخذة|multi','المتابعة|multi']},\n{group:'الرعاية الفردية',title:'فتح الحالة الفردية',fields:['اسم الطالب','الصف والفصل','وصف الحالة والوقائع|multi','الأهداف التربوية|multi','الإجراءات|multi']},\n{group:'الرعاية الفردية',title:'الجلسات الفردية',fields:['اسم الطالب','موضوع الجلسة','مجريات الجلسة|multi','التوصيات|multi']},\n{group:'الرعاية الفردية',title:'الجلسات الجماعية',fields:['الفئة المستهدفة','موضوع الجلسة','الأهداف|multi','المناقشات|multi','النتائج|multi']},\n{group:'الرعاية الفردية',title:'الخطة العلاجية',fields:['الحالة أو المشكلة','الأهداف العلاجية التربوية|multi','الإجراءات|multi','مؤشرات التقدم|multi','المتابعة|multi']},\n{group:'الرعاية الفردية',title:'الإغلاق والمتابعة',fields:['اسم الحالة','ملخص الإجراءات|multi','مبررات الإغلاق|multi','خطة المتابعة|multi']},\n{group:'الانضباط والسلوك',title:'سجل الانضباط',fields:['الصف والفصل','الواقعة|multi','الإجراءات الفعلية|multi','نتيجة المتابعة|multi']},\n{group:'الانضباط والسلوك',title:'الغياب والتأخر',fields:['اسم الطالب','الصف والفصل','نوع الحالة','التاريخ','الإجراءات|multi','المتابعة|multi']},\n{group:'الانضباط والسلوك',title:'المخالفات السلوكية',fields:['اسم الطالب','الصف والفصل','المخالفة','الدرجة','الوصف|multi','الإجراءات|multi','الحسم']},\n{group:'الانضباط والسلوك',title:'السلوك الإيجابي',fields:['اسم الطالب','الصف والفصل','السلوك المتميز','وصف الشاهد|multi','التعزيز|multi']},\n{group:'الانضباط والسلوك',title:'الحالات الطارئة',fields:['وصف الحالة|multi','الإجراء الفوري|multi','الجهة المتواصلة','المتابعة|multi']},\n{group:'التحصيل الدراسي',title:'تحليل النتائج',fields:['الصف والفصل','مصدر البيانات','نتائج التحليل|multi','التوصيات|multi']},\n{group:'التحصيل الدراسي',title:'الضعف الدراسي',fields:['اسم الطالب','المادة','مؤشرات الضعف|multi','الأسباب المحتملة|multi','الإجراء|multi']},\n{group:'التحصيل الدراسي',title:'خطة الدعم',fields:['الفئة المستهدفة','الأهداف|multi','الإجراءات|multi','الجدول الزمني','معايير النجاح|multi']},\n{group:'البرامج والأنشطة',title:'برامج الوزارة',fields:['اسم البرنامج','الفئة المستهدفة','الأهداف|multi','آلية التنفيذ|multi','النتائج الفعلية|multi','التوصيات|multi']},\n{group:'البرامج والأنشطة',title:'المبادرات',fields:['اسم المبادرة','الأهداف|multi','الفئة المستهدفة','الأعمال المنفذة|multi','المخرجات|multi']},\n{group:'البرامج والأنشطة',title:'الحضور والاستبانات',fields:['البرنامج أو الفعالية','الفئة المستهدفة','إجمالي الحضور','ملخص الاستبانة|multi','النتائج|multi']},\n{group:'البرامج والأنشطة',title:'تقرير التنفيذ',fields:['اسم العمل','الأهداف|multi','خطوات التنفيذ|multi','مؤشرات الأداء|multi','النتائج|multi','التوصيات|multi']},\n{group:'التواصل والشواهد',title:'المراسلات',fields:['المرسل إليه','الموضوع','المحتوى|multi','الإجراء المطلوب|multi']},\n{group:'التواصل والشواهد',title:'مجلس الطلاب',fields:['أعضاء المجلس|multi','جدول الأعمال|multi','القرارات|multi','المتابعة|multi']},\n{group:'التواصل والشواهد',title:'الشواهد والتوثيق',fields:['اسم العمل','وصف الشاهد|multi','ما يوثقه الشاهد|multi','ملاحظات|multi']},\n{group:'التواصل والشواهد',title:'ملف الإنجاز',fields:['مقدمة الملف|multi','ملخص الإنجازات|multi','أبرز النتائج|multi','التوصيات|multi']}\n];\nconst groups=[...new Set(catalog.map(t=>t.group))];let db,docs=[],current=null,photos=[],tab='all',group=groups[0],selected=new Set(),activeTemplate=null;\nconst storage='athat-docs-unified-v2';\nfunction say(s){$('toast').textContent=s;$('toast').style.display='block';clearTimeout(say.t);say.t=setTimeout(()=>$('toast').style.display='none',4200)}\nfunction openDb(userId){return new Promise((ok,no)=>{const r=indexedDB.open(storage+'-'+userId,1);r.onupgradeneeded=()=>r.result.createObjectStore('documents',{keyPath:'id'});r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)})}\nfunction task(mode,action){return new Promise((ok,no)=>{const t=db.transaction('documents',mode);try{action(t.objectStore('documents'))}catch(e){no(e);return}t.oncomplete=()=>ok();t.onerror=()=>no(t.error)})}\nfunction all(){return new Promise((ok,no)=>{const r=db.transaction('documents').objectStore('documents').getAll();r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)})}\nasync function refresh(){docs=await all();docs.sort((a,b)=>str(b.updated).localeCompare(str(a.updated)));draw()}\nfunction drawTemplates(){const g=$('groups');g.replaceChildren();for(const label of groups){const b=document.createElement('button');b.textContent=label;b.className=group===label?'active':'';b.onclick=()=>{group=label;drawTemplates()};g.append(b)}const el=$('templates');el.replaceChildren();catalog.filter(t=>t.group===group).forEach(t=>{const b=document.createElement('button');b.className='template';b.innerHTML='<span>▤</span><b>'+esc(t.title)+'</b><small>نموذج رسمي موحد A4</small>';b.onclick=()=>edit(null,t);el.append(b)})}\nfunction renderFields(fields,values){const el=$('officialFields');el.replaceChildren();fields.forEach((field,i)=>{const [label,kind]=field.split('|'),wrap=document.createElement('label');wrap.className=kind==='multi'?'wide':'';wrap.textContent=label;const input=document.createElement(kind==='multi'?'textarea':'input');input.dataset.field=label;input.value=str(values?.[label]);if(kind==='multi')input.rows=3;wrap.append(input);el.append(wrap)})}\n\nlet aiAuthToken='',aiSuggested={},aiBusy=false;\nconst aiSensitive=/اسم الطالب|هوية|سجل مدني|جوال|هاتف|اتصال|البريد|الصف|الفصل|تاريخ|رقم|درجة|حسم|المريض|مرض|التشخيص|الحاضرون|أعضاء|الطالب|ولي الأمر|صورة|توقيع|المرسل إليه/i;\nfunction aiAllowed(field){return !aiSensitive.test(field)}\nfunction aiStatus(message,bad=false){const node=$('aiNotice');node.textContent=message;node.classList.toggle('ai-error',bad)}\nfunction aiResetSuggestions(){aiSuggested={};$('aiSuggestions').replaceChildren();$('aiApplyAll').classList.add('hidden')}\nfunction aiSession(active){$('aiLogin').classList.toggle('hidden',active);$('aiConnected').classList.toggle('hidden',!active)}\nasync function aiRequest(url,body,token){\n const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),60000);\n try{\n  const response=await fetch(url,{method:'POST',headers:{'content-type':'application/json',...(token?{'authorization':'Bearer '+token}:{})},body:JSON.stringify(body),signal:controller.signal,cache:'no-store',credentials:'same-origin'});\n  const payload=await response.json().catch(()=>({}));\n  if(!response.ok||payload.ok===false)throw Error(payload.message||payload.code||('فشل الطلب ('+response.status+')'));\n  return payload;\n }finally{clearTimeout(timer)}\n}\n$('aiSignIn').onclick=()=>aiStatus('أنت متصل تلقائيًا بذكاء الذات عبر حساب المستندات.');\n$('aiSignOut').onclick=()=>aiStatus('لإنهاء جلسة الذكاء، استخدم تسجيل الخروج من أعلى الموقع.');\nfunction aiFields(){\n return [...$('officialFields').querySelectorAll('[data-field]')].filter(el=>aiAllowed(el.dataset.field)).map((el,index)=>({el,key:'f'+index,label:el.dataset.field,value:el.value.trim()})).slice(0,45)\n}\nfunction aiShowSuggestions(items){\n aiResetSuggestions();\n const list=$('aiSuggestions');\n for(const [label,value] of Object.entries(items)){\n  if(!aiAllowed(label)||typeof value!=='string'||!value.trim())continue;\n  aiSuggested[label]=value.slice(0,12000);\n  const item=document.createElement('div');item.className='ai-suggestion';\n  const header=document.createElement('b');header.textContent=label;\n  const body=document.createElement('p');body.textContent=aiSuggested[label];\n  const selector=document.createElement('label');selector.className='ai-confirm';\n  const check=document.createElement('input');check.type='checkbox';check.checked=true;check.dataset.aiLabel=label;\n  const caption=document.createElement('span');caption.textContent='تطبيق هذا الاقتراح بعد المراجعة';\n  selector.append(check,caption);item.append(header,body,selector);list.append(item);\n }\n $('aiApplyAll').classList.toggle('hidden',!Object.keys(aiSuggested).length);\n}\n$('aiGenerate').onclick=async()=>{\n if(aiBusy)return;\n if(!aiAuthToken)return aiStatus('اتصل بحساب الذات أولًا لاستخدام الذكاء.',true);\n if(!$('aiConsent').checked)return aiStatus('يلزم الموافقة على إرسال الوصف والحقول النصية المقترحة.',true);\n const brief=$('aiBrief').value.trim();\n if(brief.length<8)return aiStatus('اكتب وصفًا من ثمانية أحرف على الأقل.',true);\n aiBusy=true;$('aiGenerate').disabled=true;aiResetSuggestions();aiStatus('جارٍ إعداد المقترحات بواسطة خدمة ذكاء الذات…');\n try{\n  const fields=aiFields(),mode=$('aiMode').value;\n  if(mode==='fill'||mode==='rewrite'){\n   const eligible=fields.filter(f=>mode==='fill'?!f.value:!!f.value);\n   if(!eligible.length)throw Error('لا توجد حقول مناسبة لهذا الخيار.');\n   const mapping=new Map(eligible.map((f,i)=>['f'+i,f.label]));\n   const requestFields=eligible.map((f,i)=>({name:'f'+i,label:f.label,type:f.el.tagName==='TEXTAREA'?'textarea':'text'}));\n   const values=Object.fromEntries(eligible.map((f,i)=>['f'+i,mode==='rewrite'?f.value.slice(0,3000):'']));\n   const r=await aiRequest('/api/ai/smart-fill',{recordType:$('docKind').value,recordTitle:'صياغة نموذج موحد وفق الوقائع المقدمة فقط، بدون اختراع أسماء أو تواريخ أو نتائج',brief,mode:mode==='fill'?'fill':'rewrite',fields:requestFields,values},aiAuthToken);\n   aiShowSuggestions(Object.fromEntries(Object.entries(r.suggestions||{}).filter(([key])=>mapping.has(key)).map(([key,value])=>[mapping.get(key),String(value)])));\n  }else{\n   const currentText=fields.filter(f=>f.value).map(f=>f.label+': '+f.value.slice(0,1000)).join('\\n').slice(0,4000);\n   const r=await aiRequest('/api/ai/counselor',{task:mode==='summary'?'summary':'document',audience:'الموجّه الطلابي',brief,context:'النموذج: '+$('docKind').value+'. لا تخترع حقائق أو أسماء أو أعداد أو تواريخ. ضع المعلومات الناقصة بصيغة [يُستكمل].',currentText,userNote:'صياغة عربية رسمية واضحة؛ لا تفترض اكتمال أي إجراء.'},aiAuthToken);\n   const suggestion=String(r.answer|| (Array.isArray(r.bullets)?r.bullets.join('\\n'):'')).trim();\n   if(suggestion){\n    const target=fields.find(f=>/تفاصيل|وصف|الأعمال المنفذة|آلية التنفيذ|الموضوع|المحتوى|الوقائع|الملاحظات/.test(f.label))||fields.find(f=>f.el.tagName==='TEXTAREA')||fields[0];\n    if(target)aiShowSuggestions({[target.label]:suggestion});else{const b=document.createElement('p');b.className='ai-result';b.textContent=suggestion;$('aiSuggestions').append(b)}\n   }\n  }\n  aiStatus(Object.keys(aiSuggested).length?'راجع المقترحات، ثم اختر ما تريد تطبيقه. لم تتغير بيانات المستند بعد.':'لم تُرجع الخدمة مقترحات قابلة للتطبيق.');\n }catch(e){aiStatus('تعذر توليد المقترحات: '+(e.name==='AbortError'?'انتهت مهلة الاتصال.':e.message),true)}\n finally{aiBusy=false;$('aiGenerate').disabled=false}\n};\n$('aiApplyAll').onclick=()=>{\n let applied=0;\n for(const check of $('aiSuggestions').querySelectorAll('input[data-ai-label]:checked')){\n  const label=check.dataset.aiLabel,field=[...$('officialFields').querySelectorAll('[data-field]')].find(e=>e.dataset.field===label);\n  if(field&&Object.hasOwn(aiSuggested,label)&&aiAllowed(label)){\n   field.value=aiSuggested[label];field.dispatchEvent(new Event('input',{bubbles:true}));applied++;\n  }\n }\n aiResetSuggestions();aiStatus('تم تطبيق '+applied+' اقتراحًا في المحرر. راجع واحفظ المستند يدويًا.');\n};\nwindow.addEventListener('pagehide',()=>{aiAuthToken=''});\n\nfunction fieldValues(){return Object.fromEntries([...$('officialFields').querySelectorAll('[data-field]')].map(el=>[el.dataset.field,el.value]))}\nfunction edit(d,t){activeTemplate=t||catalog.find(x=>x.title===d?.kind)||catalog.at(-2);current=d?.id||null;photos=structuredClone(d?.photos||[]);$('docTitle').value=d?.title||t?.title||'';$('docKind').value=activeTemplate.title;$('docStatus').value=d?.status||'مسودة';$('schoolName').value=d?.school||'';$('documentNumber').value=d?.number||'';$('hijriDate').value=d?.hijriDate||'';renderFields(activeTemplate.fields,d?.fields||{});aiResetSuggestions();$('aiBrief').value='';$('aiConsent').checked=false;$('paperTitle').textContent=$('docTitle').value;$('editorHeading').textContent=d?'تحرير السجل الأصلي':'إنشاء '+activeTemplate.title;showPhotos();$('editor').classList.add('visible');$('editor').scrollIntoView({behavior:'smooth',block:'start'})}\n$('docTitle').oninput=e=>$('paperTitle').textContent=e.target.value;\nfunction showPhotos(){const el=$('evidencePreview');el.replaceChildren();photos.forEach((p,i)=>{const fig=document.createElement('figure');fig.className='photo';const img=document.createElement('img');img.src=p;img.alt='صورة شاهد '+(i+1);const b=document.createElement('button');b.textContent='إزالة';b.onclick=()=>{photos.splice(i,1);showPhotos()};fig.append(img,b);el.append(fig)})}\nfunction toData(file){return new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=()=>no(r.error);r.readAsDataURL(file)})}\n$('photoInput').onchange=async e=>{try{for(const file of e.target.files){if(photos.length>=10)throw Error('الحد الأقصى 10 صور لكل مستند.');if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>5*1024*1024)throw Error('تُقبل الصور JPG وPNG وWebP أقل من 5 MB.');photos.push(await toData(file))}showPhotos()}catch(err){say(err.message)}e.target.value=''};\n$('saveDoc').onclick=async()=>{try{const title=str($('docTitle').value);if(!title)throw Error('اكتب عنوان المستند.');const previous=docs.find(d=>d.id===current);const fields=fieldValues();const row={id:current||crypto.randomUUID(),title,kind:activeTemplate.title,group:activeTemplate.group,fields,body:Object.entries(fields).map(([k,v])=>k+': '+v).join('\\n\\n'),status:$('docStatus').value,school:str($('schoolName').value),number:str($('documentNumber').value),hijriDate:str($('hijriDate').value),photos:[...photos],created:previous?.created||new Date().toISOString(),updated:new Date().toISOString()};await task('readwrite',s=>s.put(row));$('editor').classList.remove('visible');await refresh();say('تم حفظ النموذج الموحد في أرشيفك المحلي')}catch(e){say('تعذر الحفظ: '+e.message)}};\n$('closeEditor').onclick=()=>$('editor').classList.remove('visible');$('newBtn').onclick=()=>edit(null,catalog[0]);\nfunction draw(){$('countAll').textContent=docs.length;$('countDone').textContent=docs.filter(d=>d.status==='مكتمل').length;$('countArchive').textContent=docs.filter(d=>d.status==='مؤرشف').length;const q=str($('search').value).toLowerCase();const rows=docs.filter(d=>(tab!=='archive'||d.status==='مؤرشف')&&(!q||(d.title+' '+d.kind+' '+d.body).toLowerCase().includes(q)));const el=$('docs');el.replaceChildren();if(!rows.length){const p=document.createElement('p');p.className='muted';p.textContent='المساحة نظيفة ولا توجد أعمال محفوظة بعد.';el.append(p)}for(const d of rows){const art=document.createElement('article');art.className='doc';if(tab==='portfolio'){const cb=document.createElement('input');cb.type='checkbox';cb.checked=selected.has(d.id);cb.setAttribute('aria-label','تحديد '+d.title);cb.onchange=()=>cb.checked?selected.add(d.id):selected.delete(d.id);art.append(cb)}const info=document.createElement('div');info.className='info';const b=document.createElement('b');b.textContent=d.title;const s=document.createElement('small');s.textContent=d.kind+' · '+d.status;info.append(b,s);art.append(info);if(tab!=='portfolio'){const open=document.createElement('button');open.textContent='فتح';open.onclick=()=>edit(d);const archive=document.createElement('button');archive.textContent=d.status==='مؤرشف'?'استعادة':'أرشفة';archive.onclick=async()=>{d.status=d.status==='مؤرشف'?'مكتمل':'مؤرشف';d.updated=new Date().toISOString();await task('readwrite',s=>s.put(d));await refresh()};art.append(open,archive)}el.append(art)}$('portfolioActions').classList.toggle('hidden',tab!=='portfolio')}\ndocument.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));draw()});$('search').oninput=draw;\n\nfunction printDocs(rows){\n if(!rows.length){say('حدد مستندًا واحدًا على الأقل للطباعة.');return;}\n const win=window.open('','_blank');\n if(!win){say('اسمح بفتح نافذة معاينة الطباعة.');return;}\n const today=new Intl.DateTimeFormat('ar-SA-u-ca-islamic-umalqura-nu-latn',{year:'numeric',month:'long',day:'numeric'}).format(new Date());\n const css=String.raw`\n @page{size:A4 portrait;margin:12mm 12mm 14mm}\n *{box-sizing:border-box}\n html,body{margin:0;padding:0;direction:rtl;color:#493622;background:#E9DEC9;font:13px/1.85 Tahoma,Arial,sans-serif;-webkit-print-color-adjust:exact;print-color-adjust:exact}\n .toolbar{position:sticky;top:0;z-index:5;background:#5A422B;color:#fff;padding:12px;display:flex;gap:10px;align-items:center;flex-wrap:wrap}\n .toolbar strong{margin-left:auto}.toolbar button{padding:9px 14px;border:0;border-radius:8px;background:#BC9C6B;color:#493622;font-weight:700;cursor:pointer}.toolbar button:disabled{opacity:.55}\n .toolbar label{display:flex;gap:5px;align-items:center;font-size:12px}.toolbar small{color:#EEE1C9}\n .content{max-width:210mm;margin:14px auto}\n .sheet{width:210mm;min-height:297mm;margin:10px auto;padding:12mm 12mm 14mm;background:#fff;box-shadow:0 3px 15px #0002;position:relative}\n .cover{display:grid;place-content:center;text-align:center;gap:10mm}.cover h1{font-size:30px}.cover .mark{display:grid;place-items:center;width:28mm;height:28mm;border-radius:50%;border:2px solid #765638;margin:auto}\n .toc h2{text-align:center}.toc li{margin:5mm 0;border-bottom:1px dotted #c6cec7}\n .document{break-before:page;page-break-before:always;min-height:0}\n .document-table{width:100%;table-layout:fixed;border-collapse:collapse}\n .document-table thead{display:table-header-group}.document-table tfoot{display:table-footer-group}\n .document-table td{vertical-align:top;padding:0}\n .letterhead{display:grid;grid-template-columns:1fr 22mm 1fr;gap:5mm;align-items:center;border-bottom:2px solid #9faea4;padding:3mm 0 5mm;margin-bottom:6mm;break-inside:avoid}\n .letterhead .org{font-size:11px;line-height:1.6;overflow-wrap:anywhere}.letterhead .stamp{border-radius:50%;height:20mm;width:20mm;border:1px solid #aebbb3;display:grid;place-content:center;text-align:center;font-weight:700;font-size:10px;line-height:1.5}\n .letterhead .ref{text-align:left;font-size:10.5px;line-height:1.7;overflow-wrap:anywhere}\n .doc-title{text-align:center;margin:5mm 0 2mm;font-size:20px;break-after:avoid}.doc-type{text-align:center;font-size:11px;color:#806E58;margin:0 0 6mm}\n .field{padding:3mm 4mm;border:1px solid #DACDB9;margin:0 0 3mm;overflow-wrap:anywhere;break-inside:avoid;page-break-inside:avoid}\n .field-row{break-inside:auto;page-break-inside:auto}.field.large{break-inside:auto;page-break-inside:auto}.field b{display:block;color:#745A3C;font-size:11px;border-bottom:1px solid #e9eee9;margin-bottom:1mm}.field p{margin:0;line-height:1.95;white-space:pre-wrap;overflow-wrap:anywhere}\n .evidence h3{font-size:15px;margin:7mm 0 3mm;border-bottom:1px solid #c9d6ce;break-after:avoid}\n .photos{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:4mm}\n .photo{margin:0;border:1px solid #DACDB9;padding:2mm;break-inside:avoid;page-break-inside:avoid;text-align:center}\n .photo img{width:100%;height:auto;max-height:80mm;object-fit:contain;display:block;margin:auto}\n .photo figcaption{font-size:10px;margin-top:2mm;color:#806E58}\n .foot{border-top:1px solid #C9B99D;padding-top:2mm;margin-top:6mm;display:flex;justify-content:space-between;font-size:9px;color:#67786e;gap:6mm}\n .foot span{overflow-wrap:anywhere}\n .no-evidence .evidence{display:none!important}.no-empty .field.blank{display:none!important}\n @media(max-width:760px){.toolbar{position:relative}.content{overflow-x:auto;max-width:100%}.sheet{margin:8px auto}}\n @media print{\n html,body{background:#fff!important;overflow:visible!important}\n .toolbar{display:none!important}.content{margin:0;max-width:none;overflow:visible}\n .sheet{width:auto;min-height:0;margin:0;padding:0;box-shadow:none;break-after:page;page-break-after:always}\n .document{break-before:page;page-break-before:always;break-after:auto;page-break-after:auto}\n .document-table thead{display:table-header-group}.document-table tfoot{display:table-footer-group}\n .cover,.toc{break-after:page;page-break-after:always}\n .sheet:last-child{break-after:auto;page-break-after:auto}\n .field:not(.large),.photo{break-inside:avoid!important}\n .field.large{break-inside:auto!important}\n }\n `;\n let body='';\n if(rows.length>1){\n  body+='<section class=\"sheet cover\"><div class=\"mark\">الذات</div><h1>ملف الإنجاز</h1><p>النماذج الموحدة A4</p><p>عدد المستندات: '+rows.length+'</p><small>'+esc(today)+'</small></section>';\n  body+='<section class=\"sheet toc\"><h2>فهرس الأعمال</h2><ol>'+rows.map(d=>'<li>'+esc(d.title)+'</li>').join('')+'</ol></section>';\n }\n for(const [index,d] of rows.entries()){\n  const entries=Object.entries(d.fields||{});\n  const fields=entries.map(([k,v])=>{\n   const value=str(v),big=value.length>350||value.split('\\n').length>8;\n   return '<tr class=\"field-row\"><td><section class=\"field '+(big?'large ':'')+(!value?'blank':'')+'\"><b>'+esc(k)+'</b><p>'+esc(value||'—')+'</p></section></td></tr>';\n  }).join('');\n  const evidence=(Array.isArray(d.photos)?d.photos:[]).filter(v=>typeof v==='string'&&/^data:image\\/(png|jpeg|webp);base64,/i.test(v)).slice(0,10);\n  const photos=evidence.length?'<section class=\"evidence\"><h3>الشواهد المصورة</h3><div class=\"photos\">'+evidence.map((p,i)=>'<figure class=\"photo\"><img src=\"'+p+'\" alt=\"صورة شاهد\"><figcaption>الشاهد '+(i+1)+'</figcaption></figure>').join('')+'</div></section>':'';\n  body+='<section class=\"sheet document\"><table class=\"document-table\"><thead><tr><td><div class=\"letterhead\"><div class=\"org\"><b>المملكة العربية السعودية</b><div>وزارة التعليم</div><div>'+esc(d.school||'اسم المدرسة / الجهة')+'</div></div><div class=\"stamp\">وزارة<br>التعليم</div><div class=\"ref\"><div>الرقم: '+esc(d.number||'—')+'</div><div>التاريخ الهجري: '+esc(d.hijriDate||'—')+'</div><div>الحالة: '+esc(d.status||'مسودة')+'</div></div></div></td></tr></thead><tfoot><tr><td><div class=\"foot\"><span>مستندات الذات | ATHAT Docs</span><span>المستند '+(index+1)+' من '+rows.length+'</span><span>'+esc(today)+'</span></div></td></tr></tfoot><tbody><tr><td><h2 class=\"doc-title\">'+esc(d.title||'مستند موحد')+'</h2><p class=\"doc-type\">'+esc(d.kind||'النماذج الموحدة A4')+'</p></td></tr>'+fields+(photos?'<tr><td>'+photos+'</td></tr>':'')+'</tbody></table></section>';\n }\n const toolbar='<div class=\"toolbar\"><strong>معاينة النماذج الموحدة A4</strong><button id=\"print-now\" disabled>تجهيز الصور…</button><button id=\"close-window\">إغلاق</button><label><input id=\"show-evidence\" type=\"checkbox\" checked> الشواهد</label><label><input id=\"show-empty\" type=\"checkbox\"> الحقول الفارغة</label><small id=\"ready-state\">جارٍ التحقق من الصور</small></div>';\n const js=String.raw`\n (function(){\n  const button=document.getElementById('print-now');\n  document.body.classList.add('no-empty');\n  document.getElementById('close-window').onclick=()=>window.close();\n  document.getElementById('show-evidence').onchange=e=>document.body.classList.toggle('no-evidence',!e.target.checked);\n  document.getElementById('show-empty').onchange=e=>document.body.classList.toggle('no-empty',!e.target.checked);\n  const images=Array.from(document.querySelectorAll('.photo img'));\n  Promise.all(images.map(img=>new Promise(resolve=>{\n   if(img.complete){resolve(img.naturalWidth>0);return}\n   img.addEventListener('load',()=>resolve(true),{once:true});\n   img.addEventListener('error',()=>resolve(false),{once:true});\n  }))).then(flags=>{\n    const fails=flags.filter(v=>!v).length;\n    button.disabled=false;button.textContent='طباعة / حفظ PDF';\n    document.getElementById('ready-state').textContent=fails?'تنبيه: '+fails+' صورة لم تُحمّل':'جاهز · '+images.length+' صورة شاهد';\n  });\n  button.onclick=()=>{if(!button.disabled)window.print()};\n })();\n `;\n // Construct the inline script tag without a literal HTML closing tag in the parent page source.\n const html='<!doctype html><html lang=\"ar\" dir=\"rtl\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>النماذج الموحدة A4</title><style>'+css+'</style></head><body>'+toolbar+'<main class=\"content\">'+body+'</main>'+'<scr'+'ipt>'+js+'</scr'+'ipt></body></html>';\n try{win.document.open();win.document.write(html);win.document.close()}catch(e){win.close();say('تعذر تجهيز الطباعة: '+(e.message||'خطأ'))}\n}\n$('printDoc').onclick=()=>{const fields=fieldValues();printDocs([{title:$('docTitle').value,kind:activeTemplate.title,school:$('schoolName').value,number:$('documentNumber').value,hijriDate:$('hijriDate').value,fields,photos}])};$('printPortfolio').onclick=()=>printDocs(docs.filter(d=>selected.has(d.id)));\n$('backupBtn').onclick=async()=>{const blob=new Blob([JSON.stringify({app:'ATHAT-DOCS-UNIFIED',version:2,documents:await all(),created:new Date().toISOString()})],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='athat-docs-unified-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)};\n$('restoreFile').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;const data=JSON.parse(await file.text());if(data.app!=='ATHAT-DOCS-UNIFIED'||!Array.isArray(data.documents))throw Error('النسخة غير صادرة من النماذج الموحدة.');if(!confirm('إضافة مستندات النسخة إلى أرشيفك الحالي؟'))return;for(const d of data.documents.slice(0,3000)){if(!d||typeof d.title!=='string'||!catalog.some(t=>t.title===d.kind))continue;const id=crypto.randomUUID();await task('readwrite',s=>s.put({...d,id,updated:new Date().toISOString(),photos:Array.isArray(d.photos)?d.photos.filter(p=>typeof p==='string'&&/^data:image\\/(png|jpeg|webp);base64,/.test(p)).slice(0,10):[]}))}await refresh();say('تم استعادة المستندات')}catch(err){say('تعذرت الاستعادة: '+err.message)}e.target.value=''};\n$('clearDocs').onclick=async()=>{if(!confirm('سيُحذف نهائيًا كل مستند وصورة شاهد محفوظة على هذا الجهاز لهذا الموقع. هل تريد المتابعة؟'))return;if(!confirm('تأكيد أخير: لا يمكن استعادة الملفات إلا من نسخة احتياطية لديك. مسح الكل؟'))return;await task('readwrite',s=>s.clear());selected.clear();await refresh();say('أصبحت مساحة العمل فارغة')};\n\nlet activeUser='',authMode='login',authBusy=false;\nfunction authMessage(v){$('authMsg').textContent=v}\nfunction changeAuth(mode){authMode=mode;$('registerNameWrap').hidden=mode!=='register';$('tabLogin').classList.toggle('selected',mode==='login');$('tabRegister').classList.toggle('selected',mode==='register');$('submitAuth').textContent=mode==='login'?'تسجيل الدخول':'إنشاء الحساب';$('passwordInput').autocomplete=mode==='login'?'current-password':'new-password';$('mfaWrap').hidden=true;$('mfaInput').value='';authMessage('')}\n$('tabLogin').onclick=()=>changeAuth('login');$('tabRegister').onclick=()=>changeAuth('register');\nfunction cleanEmail(v){const email=String(v||'').trim().toLowerCase();if(email.length>254||!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email))throw Error('أدخل بريدًا إلكترونيًا صحيحًا.');return email}\nasync function docsAuth(action,body,method='POST'){const r=await fetch('/api/auth/'+action,{method,headers:method==='POST'?{'content-type':'application/json'}:{},credentials:'same-origin',cache:'no-store',...(method==='POST'?{body:JSON.stringify(body||{})}:{})});const data=await r.json().catch(()=>({}));if(!r.ok||data.ok===false){const e=new Error(data.message||data.code||'فشل الاتصال بحساب الذات');e.code=data.code;throw e}return data}\nasync function enterDocs(user){\n if(!user||typeof user.id!=='string'||!/^usr_[\\w-]{10,}$/.test(user.id))throw Error('تعذر التحقق من هوية الحساب.');\n if(db){db.close();db=null}\n activeUser=user.id;docs=[];current=null;photos=[];selected.clear();\n db=await openDb(activeUser);await refresh();\n $('authGate').hidden=true;$('appMain').hidden=false;$('sessionPanel').hidden=false;$('accountName').textContent=String(user.name||user.loginIdentifier||'حسابي').slice(0,90);\n // Auth token remains server-side; AI routes use the same secured session cookie.\n aiAuthToken='session-cookie';aiSession(true);$('aiAccountLabel').textContent='متصل بذكاء الذات باستخدام حساب المستندات';\n}\nfunction exitDocs(){\n if(db){db.close();db=null}\n activeUser='';docs=[];current=null;photos=[];selected.clear();aiAuthToken='';aiResetSuggestions();aiSession(false);\n $('editor').classList.remove('visible');$('appMain').hidden=true;$('sessionPanel').hidden=true;$('authGate').hidden=false;$('passwordInput').value='';$('mfaInput').value='';\n}\n$('submitAuth').onclick=async()=>{\n if(authBusy)return;let email;\n try{email=cleanEmail($('emailInput').value)}catch(e){authMessage(e.message);return}\n const password=$('passwordInput').value;\n if(password.length<8){authMessage('كلمة المرور لا تقل عن 8 أحرف.');return}\n const name=$('registerName').value.trim();\n if(authMode==='register'&&!name){authMessage('أدخل الاسم لإنشاء الحساب.');return}\n authBusy=true;$('submitAuth').disabled=true;authMessage('جارٍ التحقق من الحساب…');\n try{\n  const data=await docsAuth(authMode,{loginIdentifier:email,password,...(authMode==='register'?{name,preferredRole:'teacher'}:{}),...($('mfaWrap').hidden?{}:{mfaCode:$('mfaInput').value.trim()})});\n  await enterDocs(data.user);authMessage('');$('passwordInput').value='';\n }catch(e){\n  if(e.code==='MFA_REQUIRED'){$('mfaWrap').hidden=false;authMessage('أدخل رمز المصادقة الإضافية المفعّل على حسابك.')}\n  else authMessage(e.code==='INVALID_CREDENTIALS'?'البريد الإلكتروني أو كلمة المرور غير صحيحة.':e.code==='ACCOUNT_EXISTS'?'البريد مسجل بالفعل. اختر تسجيل الدخول.':e.message);\n }finally{authBusy=false;$('submitAuth').disabled=false}\n};\n$('passwordInput').onkeydown=e=>{if(e.key==='Enter')$('submitAuth').click()};\n$('mfaInput').onkeydown=e=>{if(e.key==='Enter')$('submitAuth').click()};\n$('logoutDocs').onclick=async()=>{if(!confirm('تسجيل الخروج؟ ستبقى الأعمال محفوظة في أرشيف هذا الحساب على الجهاز.'))return;try{await docsAuth('logout',{})}catch{}exitDocs();authMessage('تم تسجيل الخروج.')};\n(async()=>{try{const data=await docsAuth('me',null,'GET');await enterDocs(data.user)}catch{exitDocs();authMessage('سجّل الدخول ببريدك الإلكتروني لفتح مستنداتك.')}})();\n\ndrawTemplates();\n})();\n</script></body></html>";
